<?php

namespace App\Http\Controllers\Api\V1;

use App\Models\{CompanyMembership, Supplier, SupplierBankAccount, SupplierBankAccountReview, SupplierBill, SupplierCreditNote, SupplierFinancialProfile, SupplierPaymentAllocation, SupplierPaymentHold};
use App\Services\{AuditLogger, AuthorizationService};
use App\Support\{Decimal, TenantContext};
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;

final class SupplierFinancialController
{
    private function tenant(): string { return (string) app(TenantContext::class)->id(); }
    private function allow(Request $r, string $permission, ?string $company = null): void { abort_unless($r->user() && app(AuthorizationService::class)->allows($r->user(), $this->tenant(), $permission, $company), 403); }
    private function supplier(Request $r, Supplier $supplier, string $permission = 'procurement.manage'): void { abort_unless($supplier->tenant_id === $this->tenant(), 404); $this->allow($r, $permission, $supplier->company_id); }
    private function profileQuery(string $tenant, ?string $company = null) { return SupplierFinancialProfile::where('tenant_id',$tenant)->when($company,fn($q)=>$q->where('company_id',$company)); }

    public function summary(Request $r): JsonResponse { $company=$r->string('company_id')->toString()?:null; $this->allow($r,'procurement.manage',$company); $t=$this->tenant(); $profiles=$this->profileQuery($t,$company); return response()->json(['data'=>['financial_profiles'=>(clone $profiles)->count(),'verified_bank_accounts'=>SupplierBankAccount::where('tenant_id',$t)->where('verification_status','verified')->where('status','active')->when($company,fn($q)=>$q->where('company_id',$company))->count(),'pending_bank_verification'=>SupplierBankAccount::where('tenant_id',$t)->whereIn('verification_status',['submitted','pending_review'])->when($company,fn($q)=>$q->where('company_id',$company))->count(),'active_payment_holds'=>SupplierPaymentHold::where('tenant_id',$t)->where('status','active')->when($company,fn($q)=>$q->where('company_id',$company))->count(),'suppliers_with_overdue_ap'=>$this->overdueSupplierCount($t,$company),'credit_exceptions'=>(clone $profiles)->whereIn('credit_hold_status',['warning','blocked'])->count()]]); }
    public function index(Request $r): JsonResponse { $company=$r->string('company_id')->toString()?:null; $this->allow($r,'procurement.manage',$company); $t=$this->tenant(); $q=SupplierFinancialProfile::where('tenant_id',$t)->with(['supplier','currency','creditCurrency'])->when($company,fn($x)=>$x->where('company_id',$company))->when($r->filled('search'),fn($x)=>$x->whereHas('supplier',fn($s)=>$s->where('name','ilike','%'.$r->string('search').'%')->orWhere('code','ilike','%'.$r->string('search').'%')))->latest('updated_at'); return response()->json(['data'=>$q->paginate(min(max($r->integer('per_page',25),10),100)),'summary'=>$this->summary($r)->getData(true)['data']]); }
    public function show(Request $r, Supplier $supplier): JsonResponse { $this->supplier($r,$supplier,'procurement.manage'); $company=$r->string('company_id')->toString()?:$supplier->company_id; $profile=$this->profileQuery($this->tenant(),$company)->where('supplier_id',$supplier->id)->with(['currency','creditCurrency'])->first(); $accounts=SupplierBankAccount::where('tenant_id',$this->tenant())->where('supplier_id',$supplier->id)->when($company,fn($q)=>$q->where('company_id',$company))->with('currency')->latest()->get()->map->safe(); return response()->json(['data'=>['supplier'=>$supplier,'profile'=>$profile,'bank_accounts'=>$accounts,'payment_holds'=>SupplierPaymentHold::where('tenant_id',$this->tenant())->where('supplier_id',$supplier->id)->where('status','active')->get()->makeHidden(['created_by','released_by']),'ap'=>$this->ap($supplier->id,$company)]]); }
    public function saveProfile(Request $r, Supplier $supplier, AuditLogger $audit): JsonResponse { $this->supplier($r,$supplier); $d=$r->validate(['company_id'=>'required|uuid','preferred_currency_id'=>'nullable|uuid','payment_terms'=>'nullable|string|max:100','default_payment_method'=>'nullable|string|max:50','credit_limit'=>['nullable','regex:/^\\d+(\\.\\d{1,6})?$/'],'credit_currency_id'=>'nullable|uuid','warning_threshold'=>['nullable','regex:/^\\d+(\\.\\d{1,6})?$/'],'credit_blocking_policy'=>'nullable|in:warning,block','financial_notes'=>'nullable|string|max:5000']); $this->allow($r,'procurement.manage',$d['company_id']); abort_unless($supplier->company_id===null||$supplier->company_id===$d['company_id'],422); $p=DB::transaction(fn()=>SupplierFinancialProfile::updateOrCreate(['tenant_id'=>$this->tenant(),'company_id'=>$d['company_id'],'supplier_id'=>$supplier->id], [...$d,'tenant_id'=>$this->tenant(),'updated_by'=>$r->user()->id])); $audit->record($r,'supplier.financial_profile.changed',$this->tenant(),$p,['company_id'=>$p->company_id]); return response()->json(['data'=>$p->fresh()]); }
    public function bankAccounts(Request $r, Supplier $supplier): JsonResponse { $this->supplier($r,$supplier,'supplier.bank.view'); $company=$r->string('company_id')->toString()?:$supplier->company_id; return response()->json(['data'=>SupplierBankAccount::where('tenant_id',$this->tenant())->where('supplier_id',$supplier->id)->when($company,fn($q)=>$q->where('company_id',$company))->with('currency')->latest()->paginate(25)->through(fn($a)=>$a->safe())]); }
    public function createBankAccount(Request $r, Supplier $supplier, AuditLogger $audit): JsonResponse { $this->supplier($r,$supplier,'supplier.bank.submit'); $d=$r->validate(['company_id'=>'required|uuid','currency_id'=>'nullable|uuid','bank_name'=>'required|string|max:200','bank_country'=>'nullable|string|max:100','bank_branch'=>'nullable|string|max:200','account_holder_name'=>'required|string|max:200','account_number'=>'nullable|string|max:100','iban'=>'nullable|string|max:100','routing_identifier'=>'nullable|string|max:100','account_type'=>'nullable|string|max:50']); $this->allow($r,'supplier.bank.submit',$d['company_id']); abort_unless($supplier->company_id===null||$supplier->company_id===$d['company_id'],422); $raw=$d['account_number']??$d['iban']??$d['routing_identifier']??null; abort_unless($raw,422,'An account number, IBAN, or routing identifier is required.'); $a=SupplierBankAccount::create(['tenant_id'=>$this->tenant(),'company_id'=>$d['company_id'],'supplier_id'=>$supplier->id,'currency_id'=>$d['currency_id']??null,'bank_name'=>$d['bank_name'],'bank_country'=>$d['bank_country']??null,'bank_branch'=>$d['bank_branch']??null,'account_holder_name'=>$d['account_holder_name'],'encrypted_account_number'=>$d['account_number']??null,'encrypted_iban'=>$d['iban']??null,'encrypted_routing_identifier'=>$d['routing_identifier']??null,'masked_reference'=>$this->mask($raw),'account_type'=>$d['account_type']??null,'verification_status'=>'draft','status'=>'active','created_by'=>$r->user()->id]); $audit->record($r,'supplier.bank_account.created',$this->tenant(),$a,['supplier_id'=>$supplier->id,'masked_reference'=>$a->masked_reference]); return response()->json(['data'=>$a->fresh('currency')->safe()],201); }
    public function submitVerification(Request $r, SupplierBankAccount $account, AuditLogger $audit): JsonResponse { $this->account($r,$account,'supplier.bank.submit'); abort_unless(in_array($account->verification_status,['draft','changes_requested'],true),422); $account->update(['verification_status'=>'pending_review']); $audit->record($r,'supplier.bank_account.verification_submitted',$this->tenant(),$account,['masked_reference'=>$account->masked_reference]); return response()->json(['data'=>$account->fresh('currency')->safe()]); }
    public function verify(Request $r, SupplierBankAccount $account, AuditLogger $audit, string $decision): JsonResponse { $this->account($r,$account,'supplier.bank.verify'); abort_unless($account->created_by!==$r->user()->id,403,'The submitter cannot verify the same beneficiary.'); $d=$r->validate(['reason'=>[$decision==='rejected'?'required':'nullable','string','max:4000']]); abort_unless(in_array($decision,['verified','rejected'],true),422); DB::transaction(function()use($account,$r,$d,$decision){$account->update(['verification_status'=>$decision,'verified_by'=>$decision==='verified'?$r->user()->id:null,'verified_at'=>$decision==='verified'?now():null,'last_reviewed_at'=>now()]); SupplierBankAccountReview::create(['tenant_id'=>$this->tenant(),'supplier_bank_account_id'=>$account->id,'reviewer_id'=>$r->user()->id,'decision'=>$decision,'reason'=>$d['reason']??null,'reviewed_at'=>now()]);}); $audit->record($r,'supplier.bank_account.'.$decision,$this->tenant(),$account,['masked_reference'=>$account->masked_reference]); return response()->json(['data'=>$account->fresh('currency')->safe()]); }
    public function setDefault(Request $r, SupplierBankAccount $account, AuditLogger $audit): JsonResponse { $this->account($r,$account,'supplier.bank.default'); abort_unless($account->verification_status==='verified'&&$account->status==='active',422,'Only verified active beneficiaries can be default.'); DB::transaction(function()use($account){SupplierBankAccount::where('tenant_id',$this->tenant())->where('company_id',$account->company_id)->where('supplier_id',$account->supplier_id)->where('currency_id',$account->currency_id)->update(['is_default'=>false]); $account->update(['is_default'=>true]);}); $audit->record($r,'supplier.bank_account.default_changed',$this->tenant(),$account,['masked_reference'=>$account->masked_reference]); return response()->json(['data'=>$account->fresh('currency')->safe()]); }
    public function holds(Request $r, Supplier $supplier): JsonResponse { $this->supplier($r,$supplier,'supplier.payment_hold.view'); return response()->json(['data'=>SupplierPaymentHold::where('tenant_id',$this->tenant())->where('supplier_id',$supplier->id)->latest()->paginate(25)]); }
    public function createHold(Request $r, Supplier $supplier, AuditLogger $audit): JsonResponse { $this->supplier($r,$supplier,'supplier.payment_hold.apply'); $d=$r->validate(['company_id'=>'required|uuid','bank_account_id'=>'nullable|uuid','hold_type'=>'required|string|max:80','reason'=>'required|string|min:2|max:4000']); $this->allow($r,'supplier.payment_hold.apply',$d['company_id']); $h=SupplierPaymentHold::create(['tenant_id'=>$this->tenant(),'company_id'=>$d['company_id'],'supplier_id'=>$supplier->id,'bank_account_id'=>$d['bank_account_id']??null,'hold_type'=>$d['hold_type'],'reason'=>$d['reason'],'status'=>'active','created_by'=>$r->user()->id,'effective_at'=>now()]); $audit->record($r,'supplier.payment_hold.applied',$this->tenant(),$h); return response()->json(['data'=>$h],201); }
    public function releaseHold(Request $r, SupplierPaymentHold $hold, AuditLogger $audit): JsonResponse { abort_unless($hold->tenant_id===$this->tenant(),404); $this->allow($r,'supplier.payment_hold.release',$hold->company_id); $d=$r->validate(['reason'=>'required|string|min:2|max:4000']); abort_unless($hold->status==='active',422); $hold->update(['status'=>'released','released_by'=>$r->user()->id,'released_at'=>now(),'release_reason'=>$d['reason']]); $audit->record($r,'supplier.payment_hold.released',$this->tenant(),$hold); return response()->json(['data'=>$hold->fresh()]); }
    private function account(Request $r, SupplierBankAccount $a, string $permission): void { abort_unless($a->tenant_id===$this->tenant(),404); $this->allow($r,$permission,$a->company_id); }
    private function mask(string $value): string { $clean=preg_replace('/\\s+/','',$value); return str_repeat('•',max(0,strlen($clean)-4)).substr($clean,-4); }
    private function overdueSupplierCount(string $tenant, ?string $company): int { return SupplierBill::where('tenant_id',$tenant)->where('state','posted')->whereNotNull('due_date')->whereDate('due_date','<',now())->when($company,fn($q)=>$q->where('company_id',$company))->distinct('supplier_id')->count('supplier_id'); }
    private function ap(string $supplier, ?string $company): array { $b=SupplierBill::where('tenant_id',$this->tenant())->where('supplier_id',$supplier)->where('state','posted')->when($company,fn($q)=>$q->where('company_id',$company))->get(); $curr=$b->pluck('currency_code')->filter()->unique(); if($curr->count()>1)return ['available'=>false,'reason'=>'Multiple currencies require an explicit FX policy.']; $out='0'; foreach($b as $bill){$paid=SupplierPaymentAllocation::where('tenant_id',$this->tenant())->where('supplier_bill_id',$bill->id)->whereHas('payment',fn($q)=>$q->where('state','posted'))->sum('amount');$credit=SupplierCreditNote::where('tenant_id',$this->tenant())->where('supplier_bill_id',$bill->id)->where('state','posted')->sum('total');$out=Decimal::add($out,Decimal::sub(Decimal::sub((string)$bill->grand_total,(string)$paid),(string)$credit));} return ['available'=>true,'currency_code'=>$curr->first(),'posted_bill_count'=>$b->count(),'outstanding'=>$out,'overdue'=>$b->filter(fn($x)=>$x->due_date&&$x->due_date->isPast())->count()]; }
}
